import pathlib,json,hashlib,time,subprocess
R=pathlib.Path(__file__).resolve().parents[1];assert not (R/'PROTOCOL.json').exists();assert not list((R/'evidence/evaluation').rglob('result.json')) and not list((R/'evidence/fresh-validation').rglob('result.json'))
models=['gpt-6-luna','gpt-6.1-sol','gpt-6-astra'];mg='google/medgemma-1.5-4b-it'
cases=[{'case_id':p.name,'modality':p.name.split('-')[0],'stage':'evaluation'} for p in sorted((R/'agent-visible/evaluation').iterdir()) if p.is_dir()]
assert len(cases)==120
paired=[x for x in cases if (x['modality']=='CXR' and (int(x['case_id'].split('-')[-1]) in [1,2,3,11,12,13,21,22,31,32] or 41<=int(x['case_id'].split('-')[-1])<=50)) or (x['modality'] in ['CT','MR'] and int(x['case_id'].split('-')[-1])<=10)]
assert len(paired)==40
control=[x for x in cases if (x['modality']=='CXR' and int(x['case_id'].split('-')[-1]) in [1,11,21,41,42]) or (x['modality']!='CXR' and int(x['case_id'].split('-')[-1])<=({'CT':3,'MR':2}[x['modality']]))]
fresh=[{'case_id':p.name,'modality':p.name.split('-')[0],'stage':'fresh-validation'} for p in sorted((R/'agent-visible/fresh-validation').iterdir()) if p.is_dir()];assert len(fresh)==30
assign=[]
def add(case,model,arm='B',config='primary',attempt=''):
 assign.append(dict(case,model=model,arm=arm,configuration=config,attempt=attempt))
for c in cases:
 for m in models+[mg]:add(c,m)
for c in paired:
 for m in models:
  add(c,m,'A');add(c,m,config='delegated');add(c,m,config='second-reader')
for c in control:
 for m in models:add(c,m,config='self-review')
 for m in models+[mg]:add(c,m,attempt='repeat1')
for c in fresh:
 for m in ['gpt-6.1-sol',mg]:add(c,m)
assert len(assign)==970
protocol={'frozen_unix':time.time(),'design':'Prospective exploratory paired study with published existing doctor reports; no live clinicians; report assertion concordance is not clinically adjudicated accuracy','cohort':cases,'paired_viewer_and_roles':paired,'control_and_repeats':control,'fresh_cases':fresh,'assignments':assign,'clinical_context':'Modality only, no history or priors; all views of one patient study','models':models+[mg],'gpt_identity':'Requested native provider identifier verified per trace; backend weights/revision not exposed','medgemma_revision':'91850547d9f0b2fdd21aa7c5f4f3d1a8a52c243b','medgemma_serving':json.loads((R/'evidence/medgemma-serving-config.json').read_text()),'medgemma_27b':'Not run: 8 GiB device cannot execute pinned full multimodal model in this bounded setup','input_B':'CXR all 1-2 released views; CT 16 uniform 5-95% axial slices, lung and mediastinal windows, four montages; MRI up to four lexical sequence-family representatives with 12 uniform axial slices each','input_A':'All released images from selected volume/study converted with audited geometry to derived DICOM in Weasis; screenshot evidence only; not necessarily complete original exam','wall_seconds':{'B':180,'A_CXR':120,'A_CT_MR':180},'viewer_steps':{'CXR':16,'CT_MR':24},'concurrency':{'codex':2,'medgemma':1,'viewer':1},'provider_requests_per_minute':6,'cost_ceiling':{'purchases':0,'authorized_allowance':'Existing Codex Pro plus one existing free banked reset; Check balance and allowance before each provider start; one existing free reset at 95% usage preserves headroom; stop at 95% after reset or any observed credit draw; shared account contention cannot be guaranteed absent','max_platform_diagnostic_requests':1000,'max_input_tokens_including_cached':100000000,'max_output_tokens':1000000,'currency_prices':'Unavailable for subscription usage; no invented dollar comparisons'},'references':'Pre-output frozen explicit report clause assertions; uncertain/conflicting/redacted assertions ambiguous, omitted findings unscorable; no model-based correctness judge','CXR_sampling':'Report-enriched 40 candidate-positive and 20 explicit-all-four-negative studies; quota 10 each target candidate positive, labels overlap, conservative audited assertions can remove candidate positivity; not population prevalence or predictive-value estimate','reference_limitations':['Public benchmark pretraining exposure unknown','Cross-dataset identity linking unavailable','OpenI released patient reports treated as study identities without external longitudinal linkage','CT reports translated by dataset authors','MR reports translated/restructured using Qwen by dataset authors; sparse assertions and no target negatives','Source studies may omit original clinical sequences'],'metrics':'Per-modality, per-label report concordance; Wilson 95% binomial intervals; completed-only confusion plus all-assigned failure denominator and missing-outcome bounds; patient-paired difference bootstrap 5000 with seed graysby-paired-bootstrap-v1, exact McNemar exploratory; no multiplicity-adjusted confirmatory claims','confidence':'Confidence refers to primary conclusion; no adjudicated primary-diagnosis gold, so Brier/ECE/AUROC calibration not estimable. Descriptive confidence only.','roles':'Delegated tool supplies cached independent blinded MedGemma B read before primary answer. Second-reader supplies saved primary B and same independent MedGemma B read in a fresh context. Self-review supplies saved primary B only. Shared cached reads counted once physically; per-configuration consult overhead stated separately. No targeted follow-up tool.','repeat_policy':'One prospectively selected fresh independent context repeat; do not inflate primary sample N','fresh_policy':'Prespecified Sol and MedGemma on 30 additional studies, not outcome-selected winner; same frozen prompts/settings','failure_policy':'One first diagnostic attempt only. Controller exceptions, timeout, required-tool missing, schema invalid, identity unresolved or wrong case retained as failures; no clinical retries or answer repairs. Infrastructure transport retry only if no clinical action/output occurred, recorded separately.','matched_screenshot_analysis':'Optional prespecified first paired case per modality/model if <=4 actual delivered screenshot frames; exact screenshots as B attachments, separate technical sensitivity set. If incompatible or no frames, explicitly not run; not pooled with primary.','decision_policy':'No clinical deployment endorsement. Research mechanical completion gate: >=95% valid completion and Wilson lower bound >=80%, clean identity/isolation audit; label clinical conclusions require both classes and wide CIs explicitly. Equivalence not inferred from nonsignificance; exploratory 5pp equivalence margin only if paired 95% CI wholly inside it. MRI binary specificity not estimable. USD ROI not estimable.','report_deadline':'2026-10-01 morning Asia/Kolkata; interim checkpoint report emitted continuously; incomplete assigned cells explicit'}
hashes={str(p.relative_to(R)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted((R/'scripts').glob('*.py'))}
refs=subprocess.check_output(['sudo','-n','cat',str(R/'scoring/references/report-references.json')]);hashes['scoring/references/report-references.json']=hashlib.sha256(refs).hexdigest()
for p in sorted((R/'agent-visible/evaluation').rglob('*.png')):hashes[str(p.relative_to(R))]=hashlib.sha256(p.read_bytes()).hexdigest()
protocol['frozen_artifact_hashes']=hashes
(R/'PROTOCOL.json').write_text(json.dumps(protocol,indent=2)+'\n');(R/'evidence/protocol-freeze.json').write_text(json.dumps({'frozen_unix':protocol['frozen_unix'],'protocol_sha256':hashlib.sha256((R/'PROTOCOL.json').read_bytes()).hexdigest(),'held_out_outputs_before_freeze':0,'assignment_count':len(assign)},indent=2))
o=json.loads((R/'ownership.json').read_text());o['limits']['max_gpt_input_tokens']=100000000;o['limits']['max_gpt_output_tokens']=1000000;(R/'ownership.json').write_text(json.dumps(o,indent=2))
print('Frozen',len(assign),'assignments',len(cases),'primary studies')
